from datetime import date


def add_years(d: date, n: int, convention: str) -> date:
    """Shift date d by n years. convention: 'clamp' (Feb29->Feb28) or 'roll' (Feb29->Mar1)."""
    if n < 0:
        raise ValueError("negative years not allowed")
    if convention not in ("clamp", "roll"):
        raise ValueError("convention must be 'clamp' or 'roll'")
    try:
        return d.replace(year=d.year + n)
    except ValueError:  # Feb 29 in a non-leap target year
        return date(d.year + n, 3, 1 if convention == "roll" else 2, 28)


def sol_simple(accrual: date, years: int) -> date:
    """Corvana rule: clamp convention; a Feb 28 reached by clamping from Feb 29 stays Feb 28."""
    return add_years(accrual, years, "clamp")
